from PIL import Image, UnidentifiedImageError

class SafeImageFolder(torchvision.datasets.ImageFolder):
    def __init__(self, root, transform=None, target_transform=None):
        super().__init__(root, transform=transform, target_transform=target_transform)
        # Filter out corrupted images during initialization
        valid_samples = []
        for path, target in self.samples:
            try:
                with Image.open(path) as img:
                    img.verify()  # Verify the image is not corrupted
                valid_samples.append((path, target))
            except (UnidentifiedImageError, IOError, OSError) as e:
                print(f"Skipping corrupted image: {path}")
        self.samples = valid_samples
        self.imgs = valid_samples
        if len(valid_samples) == 0:
            raise RuntimeError("No valid images found in dataset")
        print(f"Loaded {len(valid_samples)} valid images")

dataset = SafeImageFolder(root = "data_small/celeba_hq_256",
                          transform = transformer)

