def pil_loader(path):
    # open path as file to avoid ResourceWarning (https://github.com/python-pillow/Pillow/issues/835)
    with open(path, 'rb') as f:
        img = Image.open(f)
        return img.convert('RGB')

def collate_fn(batch):
    """
    Custom collate function to handle errors during batching
    """
    batch = list(filter(lambda x: x is not None, batch))
    if len(batch) == 0:
        return None
    return torch.utils.data.dataloader.default_collate(batch)

dataset = torchvision.datasets.ImageFolder(root = "data_small/celeba_hq_256",
                                           transform = transformer,
                                           loader=pil_loader)

# Override the __len__ to handle the case where we filter bad samples
class FilteredDataset(torch.utils.data.Dataset):
    def __init__(self, dataset):
        self.dataset = dataset
        self.valid_indices = []

        # Pre-validate indices
        print("Validating dataset...")
        for idx in range(len(dataset)):
            try:
                _ = dataset[idx]
                self.valid_indices.append(idx)
            except:
                pass

        print(f"Found {len(self.valid_indices)} valid samples out of {len(dataset)} total")

        if len(self.valid_indices) == 0:
            raise RuntimeError("No valid samples found in dataset")

    def __len__(self):
        return len(self.valid_indices)

    def __getitem__(self, idx):
        real_idx = self.valid_indices[idx]
        return self.dataset[real_idx]

# Wrap the dataset with error filtering
dataset = FilteredDataset(dataset)
